  var existN = new Set(window.PROMEZA_DATA.personas.map(function(p){return ((p.first||'')+(p.last||'')).toLowerCase().replace(/\s/g,'');}));
  var existE = new Set(window.PROMEZA_DATA.entities.map(function(e){return (e.name||'').toLowerCase().trim();}));
  var newP = extra_p.filter(function(p){return !existN.has(((p.first||'')+(p.last||'')).toLowerCase().replace(/\s/g,''));});
  var newE = extra_e.filter(function(e){return !existE.has((e.name||'').toLowerCase().trim());});
